            diagnosticReceipt(info,"player",diagnosticEntity(actor)+",sameOriginal="+(actor==fixture.rider().player())+",token="+(actor==null?null:CarriagePlayerReferences.token(actor))+",stockMatches="+(actor!=null&&ItemStack.matches(actor.getInventory().getItem(0),playerStock)));
            diagnosticReceipt(info,"journal","journalCurrent="+(journal!=null&&journal.current())+",link="+link+",matches="+(link!=null&&actor!=null&&journal.matches(link,actor))+",originDistanceSquared="+(link==null||actor==null?null:actor.position().distanceToSqr(link.origin()))+",parent="+diagnosticEntity(parent)+",mayMount="+(actor==null||parent==null?null:CarriagePassengerMountGuard.mayMount(actor,parent)));
