            for(var resource:resources)if(resource instanceof Independent independent){diagnosticReceipt(info,"independentRoot","original="+diagnosticEntity(independent.originalRoot)+",current="+(independent.originalRoot==null?null:diagnosticEntity(diagnosticLookup(h,independent.originalRoot.getUUID()))));if(independent.owner!=null){var front=independent.owner;diagnosticReceipt(info,"independentFrontend",diagnosticEntity(front)+",owned="+front.hasOwnedStructure()+",independent="+front.isIndependentNativeOwner()+",seats="+front.getContraption().getSeatMapping());diagnosticReceipt(info,"independentLedger",diagnosticLedger(diagnosticField(CarriageContraptionEntity.class,front,"independentPassengerGraphs")));}}
            extraFailureState.accept(info);
