            h.assertTrue(!body.owner.adoptCapturedOriginalRoots()&&body.owner.getPassengers().isEmpty()&&body.originalRoot.getVehicle()==outside,"Real original adoption refuses the foreign current native parent and retains the exact world-owned source");
            var snapshot=body.save();var pending=snapshot.getListOrEmpty("PendingCapturedRoots");h.assertTrue(pending.size()==1&&!snapshot.contains("IndependentPassengers")&&!snapshot.contains("Passengers"),"Native partial initialization persists only one original UUID/seat reference, without taking NPC material or player NBT");
