            if(restoreBeforeAdoption){h.assertTrue(body.owner.recoverIndependent()&&body.originalRoot.getVehicle()==outside&&state.player().getVehicle()==body.originalRoot,"Reference-only world handoff restores body blocks while respecting the original root's actual later voluntary vehicle");}
            else{body.originalRoot.stopRiding();body.owner.resumeIndependentPassengers();state.journal().tick();h.assertTrue(body.originalRoot.getVehicle()==body.owner&&state.player().getVehicle()==body.originalRoot&&body.owner.capturedRootReferences().empty(),"Ordinary source availability retries and adopts the exact original live subtree without decoding copied NPC payload");h.assertTrue(body.owner.recoverIndependent()&&body.originalRoot.getVehicle() instanceof SeatEntity,"Genuine world restoration then seats the same actual original root");}
