    /** Native observers must not throw outside the GameTest scheduler's exception boundary. */
    private static void recordNativeObservationFailure(AtomicReference<Throwable> recorded,Throwable actual){if(recorded.compareAndSet(null,actual))return;var first=recorded.get();if(first!=actual)first.addSuppressed(actual);}
    private static void captureNativeObservation(AtomicReference<Throwable> recorded,Runnable observation){if(recorded.get()!=null)return;try{observation.run();}catch(Throwable actual){recordNativeObservationFailure(recorded,actual);}}
    private static boolean nativeObservationMatches(AtomicReference<Throwable> recorded,java.util.function.BooleanSupplier predicate){if(recorded.get()!=null)return false;try{return predicate.getAsBoolean();}catch(Throwable actual){recordNativeObservationFailure(recorded,actual);return false;}}
    private static void throwNativeObservationFailure(AtomicReference<Throwable> recorded){var actual=recorded.get();if(actual==null)return;if(actual instanceof RuntimeException failure)throw failure;var reportable=new UnknownGameTestException(actual);reportable.initCause(actual);throw reportable;}
    /** Read actual native ticket values only; getTickets never adds or resets a ticket. */
