        var storage=(net.minecraft.world.level.TicketStorage)diagnosticField(net.minecraft.server.level.ServerChunkCache.class,h.getLevel().getChunkSource(),"ticketStorage");var rows=new ArrayList<String>();int x=position.getX()>>4,z=position.getZ()>>4;
